const body = $json.body ?? {};
const task = body.task ?? {};
const channels = new Set(['change_request']);
const environments = new Set(['Development', 'Staging', 'Production']);
const kinds = new Set(['Configuration']);
const validId = value => typeof value === 'string' && /^[A-Za-z0-9._-]{1,128}$/.test(value);
const targets = Array.isArray(body.targets) ? body.targets : [];
if (!channels.has(task.channel) || !validId(task.id) || !validId(task.revision) || !validId(task.projectId) || !environments.has(body.environment) || !kinds.has(body.kind) || targets.length < 1 || targets.length > 16) { throw new Error('invalid change request'); }
for (const target of targets) { if (!target || typeof target.reference !== 'string' || target.reference.length > 200 || target.reference.startsWith('/') || target.reference.includes('\\') || target.reference.includes('..') || typeof target.requestedValue !== 'string' || target.requestedValue.length > 512) throw new Error('invalid change target'); }
return [{ json: { task: { id: task.id, revision: task.revision, projectId: task.projectId, channel: task.channel }, environment: body.environment, kind: body.kind, targets } }];
